        r#"{"Command": null}"#,
        r#"{"command": "Tick", "Seconds": 1}"#,
        r#"{"Command": "Nope"}"#,
        r#"{"Command": "Tick", "Seconds": 1} trailing"#,
        r#"{"Command": "Tick", "Seconds": 1}"#,
    ]);
    for response in &out[..7] {
        assert_eq!(error_code(response), "InvalidRequest", "{response}");
    }
