    fn execute(&mut self, request: Request) -> Result<Response, Error> {
        match request {
            Request::Tick { seconds } => {
                self.now += u64::from(seconds);
                Ok(Response::Tick(TickResult { now: self.now }))
            }
        }
    }
}
