    }

    fn in_flight_mut(&mut self, key: u64, handle: u64, now: u64) -> Option<&mut Message> {
        self.messages.get_mut(&key).filter(|message| {
            message.state(now) == State::InFlight
                && message.delivery.is_some_and(|d| d.handle == handle)
        })
    }

