        &send("a"),
        r#"{"Command": "ReceiveMessage", "QueueName": "q", "VisibilityTimeout": 0}"#,
        r#"{"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-1"}"#,
        receive(),
    ]);
    assert_eq!(error_code(&out[3]), "ReceiptHandleExpired");
    assert_eq!(out[4]["Messages"][0]["ReceiveCount"], 2);
}

#[test]
