    ]);
    assert_eq!(out[4], json!({"ok": true}));
    assert_eq!(out[6]["Messages"], json!([]));
    assert_eq!(out[8]["Messages"][0]["ReceiveCount"], 2);
    assert_eq!(out[9], json!({"ok": true}));
    assert_eq!(out[10]["Messages"][0]["ReceiveCount"], 3);
